 ax[0].axhline(.05,color='#444',ls='--',label='Unchanged quiet limit');ax[0].set_title('Recorded raw velocity (not a model prediction)');ax[0].set_ylabel('Median ankle-roll qd (rad/s)');ax[0].legend()
