 fig.suptitle('Different quantities: do not subtract to claim future settling',fontsize=14);fig.tight_layout();fig.savefig(O/'velocity_and_model.png',dpi=150);plt.close(fig)
 fig,ax=plt.subplots(1,2,figsize=(13,5));ax[0].bar(x,[s['pelvis_roll_dq_bound_median']*1000 for s in late],color='#76629a');ax[0].set_ylabel('Model incremental pelvis roll envelope (mrad)');ax[1].bar(x,[s['pelvis_lateral_dq_bound_median']*1e6 for s in late],color='#548b70');ax[1].set_ylabel('Model incremental lateral displacement envelope (µm)')
 for aa in ax:aa.set_xticks(x,labels)
